function validate([node, tree]) {
  const values = tree.filter(v => v !== null);
  if (values.length < 1) return 'The tree needs at least one node.';
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (tree[0] === null) return 'The root cannot be null.';
  if (values.some(v => v < -100000 || v > 100000)) return 'Node values are between -10^5 and 10^5.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  if (!Number.isInteger(node) || !values.includes(node)) return 'node must be the value of a node in the tree.';
  // Link the level-order array, then read it in order: a BST gives strictly increasing values.
  const left = [], right = [], ids = [0];
  let next = 1;
  for (let head = 0; head < ids.length; head++) {
    for (const side of [left, right]) {
      side[ids[head]] = next < tree.length && tree[next] !== null ? next : -1;
      if (side[ids[head]] !== -1) ids.push(next);
      next++;
    }
  }
  const stack = [];
  let current = 0, previous = -Infinity;
  while (current !== -1 || stack.length) {
    while (current !== -1) { stack.push(current); current = left[current]; }
    current = stack.pop();
    if (tree[current] <= previous) return 'The tree must be a binary search tree.';
    previous = tree[current];
    current = right[current];
  }
  return null;
}

