function adapt(input, solve, kit) {
  const [node, tree] = input;
  class Node {
    constructor(val) { this.val = val; this.left = null; this.right = null; this.parent = null; }
  }
  // Build the tree level by level, linking every child back to its parent.
  const nodes = [new Node(tree[0])];
  let next = 1;
  for (let head = 0; head < nodes.length && next < tree.length; head++) {
    for (const side of ['left', 'right']) {
      if (next < tree.length && tree[next] !== null) {
        const child = new Node(tree[next]);
        child.parent = nodes[head];
        nodes[head][side] = child;
        nodes.push(child);
      }
      next++;
    }
  }
  const links = nodes.map(item => [item.val, item.left, item.right, item.parent]);
  const result = solve(nodes.find(item => item.val === node));
  const intact = nodes.every((item, i) => item.val === links[i][0] && item.left === links[i][1] && item.right === links[i][2] && item.parent === links[i][3]);
  if (!intact) throw new Error('The tree must not be modified.');
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null) return null;
  if (!nodes.includes(result)) throw new Error('Return a node of the tree, or null.');
  return result.val;
}

