function inorderSuccessor(node) {
  // Climb to the root, list every node in order with a stack, and take the one after node.
  let root = node;
  while (root.parent) root = root.parent;
  const order = [], stack = [];
  let current = root;
  while (current || stack.length) {
    while (current) { stack.push(current); current = current.left; }
    current = stack.pop();
    order.push(current);
    current = current.right;
  }
  const at = order.indexOf(node);
  return at + 1 < order.length ? order[at + 1] : null;
}

