function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 900 + pick(99) : 1 + pick(10);
  const span = large || rand() < 0.3 ? 100000 : 20;
  const used = new Set(), values = [];
  while (values.length < n) {
    const v = pick(2 * span + 1) - span;
    if (!used.has(v)) { used.add(v); values.push(v); }
  }
  // Inserting in sorted order (sometimes) gives a chain; random order gives a bushier tree.
  const shape = rand();
  if (!large && shape < 0.2) values.sort((a, b) => a - b);
  else if (!large && shape < 0.35) values.sort((a, b) => b - a);
  const root = { val: values[0], left: null, right: null };
  for (const v of values.slice(1)) {
    let at = root;
    for (;;) {
      const side = v < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = { val: v, left: null, right: null }; break; }
      at = at[side];
    }
  }
  const tree = [], queue = [root];
  for (let head = 0; head < queue.length; head++) {
    const item = queue[head];
    tree.push(item ? item.val : null);
    if (item) queue.push(item.left, item.right);
  }
  while (tree[tree.length - 1] === null) tree.pop();
  const sorted = [...values].sort((a, b) => a - b);
  const roll = rand();
  const node = roll < 0.15 ? sorted[n - 1] : roll < 0.25 ? root.val : values[pick(n)];
  return [node, tree];
}
